import { ActivatedRouteSnapshot, GuardResult, MaybeAsync, RouterStateSnapshot } from '@angular/router';
import { NgbModal } from '@ng-bootstrap/ng-bootstrap';
import { Observable, from } from 'rxjs';
import { LectureUpdateComponent } from 'app/lecture/lecture-update.component';
import { CloseEditLectureModalComponent } from 'app/lecture/close-edit-lecture-dialog/close-edit-lecture-modal.component';

/**
 * Route guard that prevents accidental data loss when leaving the lecture edit page.
 *
 * It only prompts the user when the dismiss warning is enabled and unsaved changes were made to
 * the lecture's title or period section. In that case a confirmation modal is opened and its result
 * (whether the user confirmed leaving the page) determines if the navigation is allowed to proceed.
 *
 * @param component the lecture update component that is being deactivated
 * @param currentRoute the current route snapshot
 * @param currentState the current router state snapshot
 * @param nextState the next router state snapshot
 * @returns true if the navigation may proceed, otherwise an Observable resolving to the users decision
 */
export const hasLectureUnsavedChangesGuard = (
    component: LectureUpdateComponent,
    currentRoute: ActivatedRouteSnapshot,
    currentState: RouterStateSnapshot,
    nextState: RouterStateSnapshot,
): MaybeAsync<GuardResult> => {
    if (!component.shouldDisplayDismissWarning) {
        return true;
    }

    if (!component.isChangeMadeToTitleOrPeriodSection) {
        return true;
    }

    const modalRef = inject(NgbModal).open(CloseEditLectureModalComponent, { size: 'lg', backdrop: 'static' });
    return from(modalRef.result) as Observable<boolean>;
};
